namespace IdleIntelligence.Editor {
 public static class RepairMainViews {
  public static void Build(){BuildShell();BuildLearning();var root=WorkshopUIFactory.Node("MiraCoach",null);root.AddComponent<LayoutElement>().ignoreLayout=true;var r=(RectTransform)root.transform;r.anchorMin=r.anchorMax=new Vector2(.5f,0);r.pivot=new Vector2(.5f,0);r.anchorMin=new Vector2(0,0);r.anchorMax=new Vector2(1,0);r.anchoredPosition=new Vector2(0,82);r.sizeDelta=new Vector2(-16,240);var coach=root.AddComponent<MiraCoach>();coach.Panel=r;
   var art=WorkshopUIFactory.Node("MiraPortrait",root.transform,typeof(Image)).GetComponent<Image>();art.sprite=AssetDatabase.LoadAssetAtPath<Sprite>("Assets/IdleIntelligence/Art/mira-voss.png");art.preserveAspect=true;art.raycastTarget=false;var ar=art.rectTransform;ar.anchorMin=Vector2.zero;ar.anchorMax=new Vector2(0,1);ar.offsetMin=new Vector2(0,0);ar.offsetMax=new Vector2(78,0);coach.Portrait=art;
