   var input=WorkshopUIFactory.Node("StoryNameInput",bubble.transform,typeof(Image),typeof(InputField));WorkshopUIFactory.Size(input,44);input.GetComponent<Image>().color=GameTheme.Background;coach.Name=input.GetComponent<InputField>();var text=WorkshopUIFactory.Label("Value",input.transform,"",16);Object.DestroyImmediate(text.GetComponent<LayoutElement>());WorkshopUIFactory.Fill(text.rectTransform);text.rectTransform.offsetMin=new Vector2(8,0);coach.Name.textComponent=text;var placeholder=WorkshopUIFactory.Label("NamePlaceholder",input.transform,"Name",16);Object.DestroyImmediate(placeholder.GetComponent<LayoutElement>());WorkshopUIFactory.Fill(placeholder.rectTransform);placeholder.rectTransform.offsetMin=new Vector2(8,0);placeholder.color=GameTheme.Muted;coach.Name.placeholder=placeholder;coach.Name.characterLimit=48;coach.Error=WorkshopUIFactory.Label("StoryNameError",bubble.transform,"",11,16);coach.Confirm=WorkshopUIFactory.Button("StoryChooseName",bubble.transform,"Confirm name",null);
   var actions=WorkshopUIFactory.Horizontal("StoryActions",bubble.transform,44);coach.Confirm.transform.SetParent(actions.transform,false);coach.Skip=WorkshopUIFactory.Button("StorySkipCurrent",actions.transform,"Skip",null);coach.Next=WorkshopUIFactory.Button("StoryContinue",actions.transform,"Continue",null);coach.Target=WorkshopUIFactory.Button("StoryShowTarget",actions.transform,"Show target",null);foreach(var button in new[]{coach.Skip,coach.Next,coach.Target,coach.Confirm}){button.GetComponent<LayoutElement>().minHeight=button.GetComponent<LayoutElement>().preferredHeight=44;button.GetComponentInChildren<Text>().fontSize=13;}PrefabUtility.SaveAsPrefabAsset(root,"Assets/IdleIntelligence/Resources/PixelUI/MiraCoach.prefab");Object.DestroyImmediate(root);AssetDatabase.SaveAssets();}
  static void BuildLearning(){var root=WorkshopUIFactory.Vertical("LearningCard",null);root.AddComponent<Image>();GameTheme.SurfaceOn(root.GetComponent<Image>(),GameTheme.Surface);WorkshopUIFactory.Size(root,188);var layout=root.GetComponent<VerticalLayoutGroup>();layout.padding=new RectOffset(10,10,8,8);layout.spacing=4;layout.childForceExpandHeight=false;var card=root.AddComponent<ActionCard>();card.Button=root.AddComponent<Button>();var view=root.AddComponent<LearningCard>();view.Card=card;
   var header=WorkshopUIFactory.Horizontal("Heading",root.transform,88);header.GetComponent<HorizontalLayoutGroup>().spacing=8;header.GetComponent<HorizontalLayoutGroup>().childForceExpandHeight=false;header.GetComponent<HorizontalLayoutGroup>().childAlignment=TextAnchor.MiddleCenter;var icon=WorkshopUIFactory.Node("OriginalIcon",header.transform,typeof(Image),typeof(LayoutElement));icon.GetComponent<LayoutElement>().minWidth=icon.GetComponent<LayoutElement>().preferredWidth=48;card.Icon=icon.GetComponent<Image>();card.Icon.preserveAspect=true;card.Icon.raycastTarget=false;var copy=WorkshopUIFactory.Vertical("Copy",header.transform);copy.AddComponent<LayoutElement>().flexibleWidth=1;card.Title=WorkshopUIFactory.Label("NameAndLevel",copy.transform,"",16,40);card.Title.font=GameTheme.Bold;view.Effect=card.Detail=WorkshopUIFactory.Label("CurrentAndNextEffect",copy.transform,"",14,44);view.Effect.alignment=TextAnchor.UpperLeft;
