   view.Requirement=WorkshopUIFactory.Label("Requirement",root.transform,"",13,26);view.Requirement.color=GameTheme.Muted;var actions=WorkshopUIFactory.Horizontal("Actions",root.transform,44);view.Details=WorkshopUIFactory.Button("Details",header.transform,"i",null);var detailsSize=view.Details.GetComponent<LayoutElement>();detailsSize.minWidth=detailsSize.preferredWidth=44;detailsSize.flexibleWidth=0;header.GetComponent<HorizontalLayoutGroup>().childForceExpandWidth=false;view.StartAction=WorkshopUIFactory.Button("Start",actions.transform,"Start",null);foreach(var b in new[]{view.Details,view.StartAction}){b.GetComponent<LayoutElement>().minHeight=b.GetComponent<LayoutElement>().preferredHeight=44;}GameTheme.ButtonStyle(view.StartAction,true);view.ActionLabel=view.StartAction.GetComponentInChildren<Text>();view.Progress=WorkshopUIFactory.Node("WorkProgress",root.transform,typeof(Image)).GetComponent<Image>();WorkshopUIFactory.Size(view.Progress.gameObject,4);view.Progress.sprite=GameTheme.Rounded;view.Progress.type=Image.Type.Filled;view.Progress.fillMethod=Image.FillMethod.Horizontal;view.Progress.color=GameTheme.Accent;view.Progress.raycastTarget=false;PrefabUtility.SaveAsPrefabAsset(root,"Assets/IdleIntelligence/Resources/PixelUI/LearningCard.prefab");Object.DestroyImmediate(root);}
  static void BuildShell(){UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Scenes/IdleIntelligence.unity");var game=Object.FindFirstObjectByType<GameRuntime>();var safe=game.GetComponent<MobileShell>().Laboratory.GetComponentInParent<SafeArea>().transform;safe.GetComponent<VerticalLayoutGroup>().padding=new RectOffset(0,0,0,0);safe.GetComponent<VerticalLayoutGroup>().spacing=4;
   var header=safe.Find("Header");var resources=safe.Find("Resources");var menu=header.Find("Menu")??resources.Find("Menu");if(menu!=null){menu.SetParent(resources,false);var size=menu.GetComponent<LayoutElement>();size.minWidth=size.preferredWidth=44;size.flexibleWidth=0;}header.gameObject.SetActive(false);game.SaveButton.gameObject.SetActive(false);var rh=resources.GetComponent<LayoutElement>();rh.minHeight=rh.preferredHeight=52;var rr=resources.GetComponent<HorizontalLayoutGroup>();rr.padding=new RectOffset(4,4,0,0);rr.childForceExpandWidth=false;foreach(Transform cell in resources){if(!cell.name.StartsWith("ResourceCell"))continue;var size=cell.GetComponent<LayoutElement>()??cell.gameObject.AddComponent<LayoutElement>();size.minWidth=size.preferredWidth=0;size.flexibleWidth=1;foreach(var text in cell.GetComponentsInChildren<Text>()){text.horizontalOverflow=HorizontalWrapMode.Wrap;text.verticalOverflow=VerticalWrapMode.Truncate;}}
   var content=game.Content.GetComponent<VerticalLayoutGroup>();content.padding=new RectOffset(0,0,0,8);content.spacing=4;var view=game.GetComponent<MobileShell>().Laboratory;view.GetComponent<VerticalLayoutGroup>().spacing=4;var stage=view.transform.Find("LaboratoryStage");stage.GetComponent<Image>().color=Color.clear;var vp=stage.Find("ArtViewport");if(vp!=null)WorkshopUIFactory.Fill((RectTransform)vp);var band=stage.Find("TapCaptionBand");if(band!=null)band.gameObject.SetActive(false);game.TapButton.GetComponentInChildren<Text>().text="";
   var model=view.transform.Find("ModelTraining");model.GetComponent<LayoutElement>().minHeight=model.GetComponent<LayoutElement>().preferredHeight=52;var train=view.Train.GetComponent<LayoutElement>();train.minWidth=train.preferredWidth=94;GameTheme.ButtonStyle(view.Train);view.Model.fontSize=12;view.Model.resizeTextForBestFit=false;
   foreach(var root in new[]{resources,view.transform})if(UnityEditor.PrefabUtility.IsPartOfPrefabInstance(root))UnityEditor.PrefabUtility.ApplyPrefabInstance(root.gameObject,UnityEditor.InteractionMode.AutomatedAction);UnityEditor.SceneManagement.EditorSceneManager.SaveScene(game.gameObject.scene);
  }
  static Image CostIcon(Transform parent){var image=WorkshopUIFactory.Node("ResourceIcon",parent,typeof(Image),typeof(LayoutElement)).GetComponent<Image>();image.GetComponent<LayoutElement>().minWidth=image.GetComponent<LayoutElement>().preferredWidth=20;image.preserveAspect=true;image.raycastTarget=false;return image;}

